190	/**
191	 * Run workspace setup and show appropriate toast notification.
192	 *
193	 * When one or more clone failures are caused by missing credentials (detected
194	 * via {@link CREDENTIAL_MISSING_SENTINEL}), the toast message specifically
195	 * mentions the credential issue so the user knows where to go to fix it.
196	 * Non-credential failures continue to show the generic "Failed to clone" message.
197	 *
198	 * @param {string} projectId
199	 * @param {string} workspaceId
200	 * @param {string} successMessage - Toast message shown when all repos succeed.
201	 * @returns {Promise<Object>} The setup result from the API.
202	 * @throws {Error} Re-throws API errors for the caller to handle.
203	 */
204	async function runSetup(projectId, workspaceId, successMessage) {
205	    const result = await api.workspaces.setup(projectId, workspaceId);
206	    const failures = (result && result.results || []).filter((r) => !r.success);
207	    if (failures.length > 0) {
208	        const credentialFailures = failures.filter(
209	            (f) => typeof f.error === 'string' && f.error.includes(CREDENTIAL_MISSING_SENTINEL),
210	        );
211	        const otherFailures = failures.filter(
212	            (f) => !(typeof f.error === 'string' && f.error.includes(CREDENTIAL_MISSING_SENTINEL)),
213	        );
214	
215	        if (credentialFailures.length > 0 && otherFailures.length === 0) {
216	            // All failures are credential-related.
217	            const names = credentialFailures.map((f) => f.repositoryId).join(', ');
218	            showToast(
219	                `Setup complete with credential errors. Missing credentials for: ${names}. ` +
220	                'Select a credential in each repository\'s settings.',
221	                'warning',
222	                10000,
223	            );
224	        } else if (credentialFailures.length > 0) {
225	            // Mixed: some credential failures, some generic failures.
226	            const credNames  = credentialFailures.map((f) => f.repositoryId).join(', ');
227	            const otherNames = otherFailures.map((f) => f.repositoryId).join(', ');
228	            showToast(
229	                `Setup complete with errors. Missing credentials for: ${credNames}. ` +
230	                `Failed to clone: ${otherNames}.`,
231	                'warning',
232	                10000,
233	            );
234	        } else {
235	            // No credential failures — generic message.
236	            const names = otherFailures.map((f) => f.repositoryId).join(', ');
237	            showToast(`Setup complete with errors. Failed to clone: ${names}`, 'warning', 8000);
238	        }
239	    } else {
240	        showToast(successMessage, 'success');
241	    }
242	    return result;
243	}
