774	/**
775	 * Build a health alert section element from a workspace health report.
776	 * Returns `null` when the workspace is healthy (no issues to display).
777	 *
778	 * Fix-action buttons are wired via the `callbacks` argument so the
779	 * caller can inject async handlers that match the surrounding view's
780	 * closure state (project/workspace IDs, toast helper, etc.).
781	 *
782	 * @param {{ healthy: boolean, issues: Array<{ type: string, severity: string, message: string, fixAction: string, repositoryId?: string }> }|null} healthReport
783	 * @param {{ onRegenerate: function(): Promise<void>, onSetup: function(): Promise<void> }} callbacks
784	 * @returns {HTMLElement|null}
785	 */
786	function buildHealthAlertSection(healthReport, callbacks) {
787	    if (
788	        !healthReport ||
789	        healthReport.healthy ||
790	        !Array.isArray(healthReport.issues) ||
791	        healthReport.issues.length === 0
792	    ) {
793	        return null;
794	    }
795	
796	    const section = document.createElement('div');
797	    section.className = 'health-alert';
798	
799	    const title = document.createElement('div');
800	    title.className = 'health-alert-title';

 801	    title.textContent = 'Workspace health issues detected';
 802	    section.appendChild(title);
 803	
 804	    for (const issue of healthReport.issues) {
 805	        const row = document.createElement('div');
 806	        row.className = 'health-alert-issue';
 807	
 808	        const msg = document.createElement('span');
 809	        msg.className = 'health-alert-issue__message';
 810	        msg.textContent = issue.message;
 811	        row.appendChild(msg);
 812	
 813	        if (issue.fixAction === 'regenerate-workspace-file') {
 814	            const actionWrap = document.createElement('span');
 815	            actionWrap.className = 'health-alert-issue__action';
 816	
 817	            const btn = document.createElement('button');
 818	            btn.type = 'button';
 819	            btn.className = 'btn btn-secondary btn-sm';
 820	            btn.textContent = 'Regenerate File';
 821	            btn.addEventListener('click', async () => {
 822	                btn.disabled = true;
 823	                btn.textContent = 'Regenerating\u2026';
 824	                try {
 825	                    await callbacks.onRegenerate();
 826	                } finally {
 827	                    btn.disabled = false;
 828	                    btn.textContent = 'Regenerate File';
 829	                }
 830	            });
 831	            actionWrap.appendChild(btn);
 832	            row.appendChild(actionWrap);
 833	        } else if (issue.fixAction === 'setup-workspace') {
 834	            const actionWrap = document.createElement('span');
 835	            actionWrap.className = 'health-alert-issue__action';
 836	
 837	            const btn = document.createElement('button');
